 * @param {calIAttendee[]} [options.attendees=[]] - Event Attendees.
 * @returns {CalEvent} - The created event.
 */
async function createEvent({
  name = "Test Event",
  baseDate = todayDate,
  offset = 0,
  duration = 1,
  calendar,
  categories = [],
  repeats = false,
  location,
  description = "",
  descriptionHTML,
  alarms = [],
  attachments = [],
  attendees = [],
} = {}) {
  let start = new Date(baseDate);
  start.setDate(baseDate.getDate() + offset);
  start = cal.dtz.jsDateToDateTime(start, 0);
  let end = new Date(baseDate);
  const days = Math.trunc(duration / 24);
  end.setHours(end.getHours() + (duration % 24) - 1);
  end.setMinutes(59);
  end.setSeconds(59);
  end.setMilliseconds(99);
  end.setDate(baseDate.getDate() + offset + days);
  end = cal.dtz.jsDateToDateTime(end, 0);
  const event = new CalEvent();

  for (const attendeeData of attendees) {
    const attendee = new CalAttendee();
    for (const [key, value] of Object.entries(attendeeData)) {
      attendee[key] = value;
    }
    event.addAttendee(attendee);
  }
